#!/bin/bash
# Uninstall script for BrowserStack Local Testing
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling BrowserStack Local Testing..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping BrowserStack Local Testing if running..."
pkill -f "BrowserStack Local Testing" 2>/dev/null || true

# Unload service com.browserstack.local
echo "Unloading service com.browserstack.local..."
launchctl unload -w /Library/LaunchAgents/com.browserstack.local.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.browserstack.local.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.browserstack.local.plist 2>/dev/null || true

# Remove /Applications/BrowserStackLocal.app
echo "Removing /Applications/BrowserStackLocal.app..."
if [ -d "/Applications/BrowserStackLocal.app" ]; then
    rm -rf "/Applications/BrowserStackLocal.app" 2>/dev/null || true
elif [ -f "/Applications/BrowserStackLocal.app" ]; then
    rm -f "/Applications/BrowserStackLocal.app" 2>/dev/null || true
fi

# Remove $HOME/.browserstack
echo "Removing $HOME/.browserstack..."
if [ -d "$HOME/.browserstack" ]; then
    rm -rf "$HOME/.browserstack" 2>/dev/null || true
elif [ -f "$HOME/.browserstack" ]; then
    rm -f "$HOME/.browserstack" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/com.browserstack.Local
echo "Removing $HOME/Library/Caches/com.browserstack.Local..."
if [ -d "$HOME/Library/Caches/com.browserstack.Local" ]; then
    rm -rf "$HOME/Library/Caches/com.browserstack.Local" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/com.browserstack.Local" ]; then
    rm -f "$HOME/Library/Caches/com.browserstack.Local" 2>/dev/null || true
fi

# Remove $HOME/Library/HTTPStorages/com.browserstack.local
echo "Removing $HOME/Library/HTTPStorages/com.browserstack.local..."
if [ -d "$HOME/Library/HTTPStorages/com.browserstack.local" ]; then
    rm -rf "$HOME/Library/HTTPStorages/com.browserstack.local" 2>/dev/null || true
elif [ -f "$HOME/Library/HTTPStorages/com.browserstack.local" ]; then
    rm -f "$HOME/Library/HTTPStorages/com.browserstack.local" 2>/dev/null || true
fi

# Remove $HOME/Library/HTTPStorages/com.browserstack.local.binarycookies
echo "Removing $HOME/Library/HTTPStorages/com.browserstack.local.binarycookies..."
if [ -d "$HOME/Library/HTTPStorages/com.browserstack.local.binarycookies" ]; then
    rm -rf "$HOME/Library/HTTPStorages/com.browserstack.local.binarycookies" 2>/dev/null || true
elif [ -f "$HOME/Library/HTTPStorages/com.browserstack.local.binarycookies" ]; then
    rm -f "$HOME/Library/HTTPStorages/com.browserstack.local.binarycookies" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.browserstack.local.plist
echo "Removing $HOME/Library/Preferences/com.browserstack.local.plist..."
if [ -d "$HOME/Library/Preferences/com.browserstack.local.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.browserstack.local.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.browserstack.local.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.browserstack.local.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
